function ExercisePicker({library,value,onChange,inline=false}:{library:Exercise[];value:string;onChange:(v:string)=>void;inline?:boolean}){const [query,setQuery]=useState('');useEffect(()=>{if(inline)setQuery(library.find(e=>e.id===value)?.name??'')},[value,inline]);if(inline){const matches=library.filter(e=>e.name.toLowerCase().includes(query.toLowerCase()));return <div className="stack"><input className="planfit-select" type="search" aria-label="Search exercises" placeholder="Search exercises" value={query} onChange={event=>setQuery(event.target.value)}/><div role="listbox" aria-label="Matching exercises" style={{maxHeight:180,overflowY:'auto'}}>{matches.map(e=><button type="button" role="option" aria-selected={value===e.id} key={e.id} className="text-button" style={{display:'block',width:'100%',minHeight:44,textAlign:'left'}} onClick={()=>onChange(e.id)}>{e.name}</button>)}{!matches.length&&<p className="muted">No matching exercise</p>}</div></div>}return <Combobox items={library.map(e=>e.name)} value={library.find(e=>e.id===value)?.name??null} onValueChange={(v)=>{const e=library.find(e=>e.name===v);if(e)onChange(e.id)}}><ComboboxInput placeholder="Search exercises" aria-label="Search exercises" className="exercise-picker"/><ComboboxContent className="select-content"><ComboboxEmpty>No matching exercise</ComboboxEmpty><ComboboxList>{(name:string)=><ComboboxItem key={name} value={name}>{name}</ComboboxItem>}</ComboboxList></ComboboxContent></Combobox>}

